export const userRegistrationPageHtml = "<good-main-view>\n  <good-section>\n    <good-breadcrumbs [items]=\"breadcrumbs\" />\n    <good-heading-group>\n      <good-heading>User registration</good-heading>\n      <good-summary>A complete registration form composed entirely from GoodUI components</good-summary>\n    </good-heading-group>\n    <example-user-registration-form />\n    <ng-content />\n  </good-section>\n</good-main-view>\n";
export const userRegistrationPageTs = "import { ChangeDetectionStrategy, Component } from '@angular/core';\nimport {\n  GoodBreadcrumbsComponent, GoodHeadingComponent, GoodHeadingGroupComponent,\n  GoodMainViewComponent, GoodSectionComponent, GoodSummaryComponent, type GoodBreadcrumbItem,\n} from '@goodui/angular';\nimport { UserRegistrationFormExampleComponent } from './user-registration-form';\n\n@Component({\n  selector: 'example-user-registration-page',\n  standalone: true,\n  imports: [GoodMainViewComponent, GoodSectionComponent, GoodBreadcrumbsComponent,\n    GoodHeadingGroupComponent, GoodHeadingComponent, GoodSummaryComponent,\n    UserRegistrationFormExampleComponent],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  templateUrl: './user-registration-page.html',\n})\nexport class UserRegistrationPageComponent {\n  readonly breadcrumbs: readonly GoodBreadcrumbItem[] = [\n    { label: 'Home', route: '/dashboard' },\n    { label: 'Examples' },\n    { label: 'User registration' },\n  ];\n}\n";
export const userRegistrationFormHtml = "<form goodForm layout=\"vertical\" [fullWidth]=\"true\" [formGroup]=\"form\" (ngSubmit)=\"createUser()\" novalidate>\n  <good-group title=\"Personal details\" [headingLevel]=\"2\">\n    <good-radio-group label=\"Title\" orientation=\"horizontal\" [options]=\"salutations\"\n      formControlName=\"salutation\" />\n    <good-form-row [columns]=\"3\">\n      <good-form-field [required]=\"true\">\n        <good-field-label forId=\"registration-first-name\">First name</good-field-label>\n        <good-input inputId=\"registration-first-name\" label=\"First name\" autocomplete=\"given-name\"\n          formControlName=\"firstName\" [error]=\"isInvalid('firstName')\" />\n        @if (isInvalid('firstName')) { <good-error-text>Enter your first name.</good-error-text> }\n      </good-form-field>\n      <good-form-field>\n        <good-field-label forId=\"registration-middle-name\">Middle name</good-field-label>\n        <good-input inputId=\"registration-middle-name\" label=\"Middle name\" autocomplete=\"additional-name\"\n          formControlName=\"middleName\" />\n      </good-form-field>\n      <good-form-field [required]=\"true\">\n        <good-field-label forId=\"registration-last-name\">Last name</good-field-label>\n        <good-input inputId=\"registration-last-name\" label=\"Last name\" autocomplete=\"family-name\"\n          formControlName=\"lastName\" [error]=\"isInvalid('lastName')\" />\n        @if (isInvalid('lastName')) { <good-error-text>Enter your last name.</good-error-text> }\n      </good-form-field>\n    </good-form-row>\n  </good-group>\n  <good-group title=\"Address\" [headingLevel]=\"2\">\n    <good-form-field [required]=\"true\">\n      <good-field-label forId=\"registration-street\">Street address</good-field-label>\n      <good-input inputId=\"registration-street\" label=\"Street address\" autocomplete=\"street-address\"\n        formControlName=\"streetAddress\" [error]=\"isInvalid('streetAddress')\" />\n      @if (isInvalid('streetAddress')) { <good-error-text>Enter your street address.</good-error-text> }\n    </good-form-field>\n    <good-form-row [columns]=\"3\">\n      <good-form-field [required]=\"true\">\n        <good-field-label forId=\"registration-postal-code\">Postal code</good-field-label>\n        <good-input inputId=\"registration-postal-code\" label=\"Postal code\" autocomplete=\"postal-code\"\n          formControlName=\"postalCode\" [error]=\"isInvalid('postalCode')\" />\n        @if (isInvalid('postalCode')) { <good-error-text>Enter your postal code.</good-error-text> }\n      </good-form-field>\n      <good-form-field [required]=\"true\">\n        <good-field-label forId=\"registration-city\">City</good-field-label>\n        <good-input inputId=\"registration-city\" label=\"City\" autocomplete=\"address-level2\"\n          formControlName=\"city\" [error]=\"isInvalid('city')\" />\n        @if (isInvalid('city')) { <good-error-text>Enter your city.</good-error-text> }\n      </good-form-field>\n      <good-form-field>\n        <good-select-country label=\"Country\" [showLabel]=\"true\" [required]=\"true\"\n          formControlName=\"country\" [error]=\"isInvalid('country')\" />\n        @if (isInvalid('country')) { <good-error-text>Select a country.</good-error-text> }\n      </good-form-field>\n    </good-form-row>\n  </good-group>\n  <good-group title=\"Contact details\" appearance=\"contrast\" [headingLevel]=\"2\">\n    <good-form-row>\n      <good-form-field>\n        <good-field-label forId=\"registration-phone\">Phone number</good-field-label>\n        <good-input-phone inputId=\"registration-phone\" label=\"Phone number\" formControlName=\"phone\"\n          [country]=\"form.controls.country.value\" [error]=\"isInvalid('phone')\" />\n        <good-hint>Optional landline number.</good-hint>\n      </good-form-field>\n      <good-form-field [required]=\"true\">\n        <good-field-label forId=\"registration-mobile\">Mobile number</good-field-label>\n        <good-input-phone inputId=\"registration-mobile\" label=\"Mobile number\" formControlName=\"mobile\"\n          [country]=\"form.controls.country.value\" [error]=\"isInvalid('mobile')\" />\n        @if (isInvalid('mobile')) { <good-error-text>Enter a mobile number.</good-error-text> }\n      </good-form-field>\n    </good-form-row>\n    <good-form-field [required]=\"true\">\n      <good-field-label forId=\"registration-email\">Email address</good-field-label>\n      <good-input inputId=\"registration-email\" label=\"Email address\" type=\"email\" autocomplete=\"email\"\n        formControlName=\"email\" [error]=\"isInvalid('email')\" />\n      @if (isInvalid('email')) { <good-error-text>Enter a valid email address.</good-error-text> }\n    </good-form-field>\n  </good-group>\n  <good-group title=\"Preferences\" [headingLevel]=\"2\">\n    <good-listbox label=\"Interests\" [showLabel]=\"true\" [groups]=\"interestGroups\"\n      selectionMode=\"multiple\" appearance=\"checkbox\" formControlName=\"interests\" />\n    <good-hint>Optional. Select any interests you would like to share.</good-hint>\n  </good-group>\n  <good-group title=\"Account security\" [headingLevel]=\"2\">\n    <good-form-row>\n      <good-form-field [required]=\"true\">\n        <good-field-label forId=\"registration-password\">Password</good-field-label>\n        <good-input inputId=\"registration-password\" label=\"Password\" type=\"password\" autocomplete=\"new-password\"\n          formControlName=\"password\" [error]=\"isInvalid('password')\" />\n        @if (isInvalid('password')) { <good-error-text>Enter a password.</good-error-text> }\n      </good-form-field>\n      <good-form-field [required]=\"true\">\n        <good-field-label forId=\"registration-confirm-password\">Confirm password</good-field-label>\n        <good-input inputId=\"registration-confirm-password\" label=\"Confirm password\" type=\"password\"\n          autocomplete=\"new-password\" formControlName=\"confirmPassword\"\n          [error]=\"isInvalid('confirmPassword') || confirmationMismatch()\" />\n        @if (confirmationMismatch()) { <good-error-text>Passwords must match.</good-error-text> }\n        @else if (isInvalid('confirmPassword')) { <good-error-text>Confirm your password.</good-error-text> }\n      </good-form-field>\n    </good-form-row>\n  </good-group>\n  <good-action-group><good-button type=\"submit\">Create user</good-button></good-action-group>\n  @if (submitted() && form.invalid) {\n    <good-error-text>Review the highlighted fields before creating a user.</good-error-text>\n  }\n</form>\n@if (createdUser(); as user) {\n  <good-card>\n    <good-card-header title=\"User created in this demo\" />\n    <good-paragraph>{{ user.name }} · {{ user.email }}</good-paragraph>\n    @if (user.interests.length) { <good-paragraph>Interests: {{ user.interests.join(', ') }}</good-paragraph> }\n    <good-hint>This example validates locally and does not save the user to a server.</good-hint>\n  </good-card>\n}\n";
export const userRegistrationFormTs = "import { ChangeDetectionStrategy, Component, signal } from '@angular/core';\nimport { takeUntilDestroyed } from '@angular/core/rxjs-interop';\nimport { FormControl, FormGroup, ReactiveFormsModule, ValidatorFn, Validators } from '@angular/forms';\nimport {\n  GoodActionGroupComponent, GoodButtonComponent, GoodCardComponent, GoodCardHeaderComponent,\n  GoodErrorTextComponent, GoodFieldLabelComponent, GoodFormDirective, GoodFormFieldComponent,\n  GoodFormRowComponent, GoodGroupComponent, GoodHintComponent, GoodInputComponent,\n  GoodInputPhoneComponent, GoodListboxComponent, GoodListboxGroup, GoodParagraphComponent,\n  GoodRadioGroupComponent, GoodSelectCountryComponent,\n} from '@goodui/angular';\n\nconst passwordsMatch: ValidatorFn = form => {\n  const password = form.get('password')?.value;\n  const confirmation = form.get('confirmPassword')?.value;\n  return password && confirmation && password !== confirmation ? { passwordsMismatch: true } : null;\n};\n\n@Component({\n  selector: 'example-user-registration-form', standalone: true,\n  imports: [ReactiveFormsModule, GoodActionGroupComponent, GoodButtonComponent, GoodCardComponent,\n    GoodCardHeaderComponent, GoodErrorTextComponent, GoodFieldLabelComponent, GoodFormDirective,\n    GoodFormFieldComponent, GoodFormRowComponent, GoodGroupComponent, GoodHintComponent,\n    GoodInputComponent, GoodInputPhoneComponent, GoodListboxComponent, GoodParagraphComponent, GoodRadioGroupComponent,\n    GoodSelectCountryComponent],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  templateUrl: './user-registration-form.html',\n})\nexport class UserRegistrationFormExampleComponent {\n  readonly form = new FormGroup({\n    salutation: new FormControl('none', { nonNullable: true }),\n    firstName: new FormControl('', { nonNullable: true, validators: Validators.required }),\n    middleName: new FormControl('', { nonNullable: true }),\n    lastName: new FormControl('', { nonNullable: true, validators: Validators.required }),\n    streetAddress: new FormControl('', { nonNullable: true, validators: Validators.required }),\n    postalCode: new FormControl('', { nonNullable: true, validators: Validators.required }),\n    city: new FormControl('', { nonNullable: true, validators: Validators.required }),\n    country: new FormControl<string | null>(null, Validators.required),\n    phone: new FormControl('', { nonNullable: true }),\n    mobile: new FormControl('', { nonNullable: true, validators: Validators.required }),\n    email: new FormControl('', { nonNullable: true, validators: [Validators.required, Validators.email] }),\n    interests: new FormControl<readonly string[]>([], { nonNullable: true }),\n    password: new FormControl('', { nonNullable: true, validators: Validators.required }),\n    confirmPassword: new FormControl('', { nonNullable: true, validators: Validators.required }),\n  }, { validators: passwordsMatch });\n  readonly submitted = signal(false);\n  readonly salutations = [\n    { value: 'mr', label: 'Mr.' },\n    { value: 'ms', label: 'Ms.' },\n    { value: 'none', label: 'No title' },\n  ];\n  readonly interestGroups: readonly GoodListboxGroup[] = [\n    { id: 'creative', label: 'Creative', items: [\n      { id: 'design', label: 'Design' },\n      { id: 'photography', label: 'Photography' },\n    ] },\n    { id: 'outdoors', label: 'Outdoors', items: [\n      { id: 'hiking', label: 'Hiking' },\n      { id: 'gardening', label: 'Gardening' },\n    ] },\n  ];\n  readonly createdUser = signal<{ name: string; email: string; interests: readonly string[] } | null>(null);\n\n  constructor() {\n    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.createdUser.set(null));\n  }\n\n  isInvalid(name: keyof typeof this.form.controls): boolean {\n    const control = this.form.controls[name];\n    return control.invalid && (control.touched || this.submitted());\n  }\n\n  confirmationMismatch(): boolean {\n    return this.form.hasError('passwordsMismatch') &&\n      (this.form.controls.confirmPassword.touched || this.submitted());\n  }\n\n  createUser(): void {\n    this.submitted.set(true);\n    this.form.markAllAsTouched();\n    if (this.form.invalid) return;\n    const user = this.form.getRawValue();\n    const interestLabels = this.interestGroups.flatMap(group => group.items)\n      .filter(item => user.interests.includes(item.id)).map(item => item.label);\n    this.createdUser.set({\n      name: [user.firstName, user.middleName, user.lastName].filter(Boolean).join(' '),\n      email: user.email,\n      interests: interestLabels,\n    });\n  }\n}\n";
